insert into public.businesses (id, owner_id, slug, name, tagline, description, category_id, location_id, seller_type, verified, hours, offers_delivery, delivery_note, is_demo, created_at, updated_at) values
  ('df130ff3-8f06-5a8a-81a9-462589ab1af2', '4452f613-f21d-5d31-a867-e2d973dc665a', 'daniels-closet', 'Daniel''s Closet', 'Clean streetwear and sneakers, sourced and checked.', 'I sell authentic sneakers and everyday streetwear. Every pair is checked before listing. Pickup at Daniel Hall after 4pm on weekdays.', (select id from public.categories where slug = 'fashion'), (select id from public.locations where slug = 'daniel-hall'), 'student', true, '{"mon":[["16:00","21:00"]],"tue":[["16:00","21:00"]],"wed":[["16:00","21:00"]],"thu":[["16:00","21:00"]],"fri":[["16:00","21:00"]],"sat":[["10:00","18:00"]]}'::jsonb, false, null, true, now() - interval '57600 minutes', now() - interval '5760 minutes'),
  ('293b75c8-0da1-5c17-8910-68af93b578c2', '10b07ce1-080b-55c9-a9ea-22d4ff1be23e', 'campus-bites', 'Campus Bites', 'Hot meals near Cafeteria 2, delivered to your hall.', 'Freshly cooked rice dishes, shawarma and drinks. Orders placed before 7pm are delivered the same evening.', (select id from public.categories where slug = 'food'), (select id from public.locations where slug = 'cafeteria-2'), 'business', true, '{"mon":[["08:00","20:00"]],"tue":[["08:00","20:00"]],"wed":[["08:00","20:00"]],"thu":[["08:00","20:00"]],"fri":[["08:00","20:00"]],"sat":[["08:00","20:00"]],"sun":[["14:00","19:00"]]}'::jsonb, true, 'Delivery to any hall for ₦300, 30–45 min.', true, now() - interval '67680 minutes', now() - interval '1440 minutes'),
  ('5defc22c-0846-54db-a054-b40e04270895', '8ec02b06-c9a7-5639-a3d7-e1eb4eb63e85', 'cu-tech-hub', 'CU Tech Hub', 'Chargers, earbuds and laptop accessories that actually last.', 'Original accessories with a 7-day replacement warranty. Find us at the Student Centre, ground floor.', (select id from public.categories where slug = 'electronics'), (select id from public.locations where slug = 'student-centre'), 'business', true, '{"mon":[["10:00","18:00"]],"tue":[["10:00","18:00"]],"wed":[["10:00","18:00"]],"thu":[["10:00","18:00"]],"fri":[["10:00","18:00"]],"sat":[["11:00","16:00"]]}'::jsonb, true, 'Free delivery to halls on orders over ₦15,000.', true, now() - interval '103680 minutes', now() - interval '7200 minutes'),
  ('4eb510bb-aad6-562f-818a-9396b7e14d9c', '77358fc3-0277-59ba-b808-f1fbf3e9dec8', 'fresh-cuts', 'Fresh Cuts', 'Clean cuts in Peter Hall. Book ahead on weekends.', 'Barbing in Peter Hall with clippers sanitised between every client. Message to book a slot.', (select id from public.categories where slug = 'hair-beauty'), (select id from public.locations where slug = 'peter-hall'), 'student', true, '{"mon":[["16:00","21:00"]],"tue":[["16:00","21:00"]],"wed":[["16:00","21:00"]],"thu":[["16:00","21:00"]],"fri":[["16:00","21:00"]],"sat":[["10:00","18:00"]]}'::jsonb, false, null, true, now() - interval '61920 minutes', now() - interval '4320 minutes'),
  ('da105b33-c287-5ed6-806c-43d43e4d9011', '4ba47aa7-a83b-5b25-b2b8-cc3010ed4e20', 'the-thrift-room', 'The Thrift Room', 'Hand-picked thrift, washed and ready to wear.', 'Curated thrift pieces from Yaba and Katangua. Everything is washed and steamed before listing.', (select id from public.categories where slug = 'thrift'), (select id from public.locations where slug = 'esther-hall'), 'student', true, '{"mon":[["16:00","21:00"]],"tue":[["16:00","21:00"]],"wed":[["16:00","21:00"]],"thu":[["16:00","21:00"]],"fri":[["16:00","21:00"]],"sat":[["10:00","18:00"]]}'::jsonb, false, null, true, now() - interval '79200 minutes', now() - interval '2880 minutes'),
  ('bd3b6969-f8a1-5651-8e92-43bdca012c9c', 'b6e69488-3208-51a7-bb99-f7afb08edfef', 'sweet-crumbs', 'Sweet Crumbs by Ife', 'Birthday cakes, cupcakes and cookies baked in Mary Hall.', 'Home-baked treats for birthdays, roomie surprises and late-night cravings. Custom cakes need 48 hours'' notice.', (select id from public.categories where slug = 'food'), (select id from public.locations where slug = 'mary-hall'), 'student', true, '{"mon":[["16:00","21:00"]],"tue":[["16:00","21:00"]],"wed":[["16:00","21:00"]],"thu":[["16:00","21:00"]],"fri":[["16:00","21:00"]],"sat":[["10:00","18:00"]]}'::jsonb, true, 'Delivery within campus for ₦500. Cakes need 48 hours'' notice.', true, now() - interval '60480 minutes', now() - interval '4320 minutes'),
  ('a60bc7ef-4dda-57e1-b0e6-023cd5ac00ab', 'ef748b6b-33fc-5cf8-9225-0698237b4c21', 'glow-by-tolu', 'Glow by Tolu', 'Simple skincare for campus life.', 'Skincare I actually use, in small sizes that fit a student budget. Pickup at Deborah Hall.', (select id from public.categories where slug = 'beauty'), (select id from public.locations where slug = 'deborah-hall'), 'student', false, '{"mon":[["16:00","21:00"]],"tue":[["16:00","21:00"]],"wed":[["16:00","21:00"]],"thu":[["16:00","21:00"]],"fri":[["16:00","21:00"]],"sat":[["10:00","18:00"]]}'::jsonb, false, null, true, now() - interval '14400 minutes', now() - interval '5760 minutes'),
  ('c2f1cde1-1980-5575-8f0b-e72dd7d8e390', 'c35639cd-431b-549c-8cf2-fa783964a49a', 'lens-and-light', 'Lens & Light Studios', 'Portraits, convocation shoots and event coverage.', 'Photographers based at the Student Centre. Edited photos are delivered within 5 days by Google Drive.', (select id from public.categories where slug = 'photography'), (select id from public.locations where slug = 'student-centre'), 'business', true, '{"mon":[["10:00","18:00"]],"tue":[["10:00","18:00"]],"wed":[["10:00","18:00"]],"thu":[["10:00","18:00"]],"fri":[["10:00","18:00"]],"sat":[["11:00","16:00"]]}'::jsonb, false, null, true, now() - interval '57600 minutes', now() - interval '2880 minutes'),
  ('ad92093c-941c-5d21-a7c8-1f748156a8b8', 'f9536b70-03d3-5fef-b185-3cc943edeeb8', 'page-turner-books', 'Page Turner Books', 'Used textbooks and past questions, half the price.', 'Second-hand textbooks from final-year students. Pickup near the Centre for Learning Resources.', (select id from public.categories where slug = 'books'), (select id from public.locations where slug = 'library'), 'student', false, '{"mon":[["16:00","21:00"]],"tue":[["16:00","21:00"]],"wed":[["16:00","21:00"]],"thu":[["16:00","21:00"]],"fri":[["16:00","21:00"]],"sat":[["10:00","18:00"]]}'::jsonb, false, null, true, now() - interval '64800 minutes', now() - interval '0 minutes'),
